using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Sigov.Application.Bloco8; using Sigov.Application.Common; using Sigov.Domain.Common;
namespace Sigov.Api.Controllers;
[ApiController,Authorize] public sealed class AtendimentoPublicoController:ControllerBase { private readonly IEsicService _esic;private readonly IOuvidoriaService _ouv;public AtendimentoPublicoController(IEsicService esic,IOuvidoriaService ouv){_esic=esic;_ouv=ouv;} [HttpGet("api/esic/pedidos")]public async Task<ActionResult<ApiResponse<PagedResult<Bloco8RegistroDto>>>> Esic(CancellationToken ct)=>From(await _esic.ListarAsync("esic_pedido",1,20,ct));[HttpPost("api/esic/pedidos")]public async Task<ActionResult<ApiResponse<long>>> CriarEsic(Bloco8RegistroRequest r,CancellationToken ct)=>From(await _esic.CriarAsync("esic_pedido",r,HttpContext.TraceIdentifier,ct));[HttpGet("api/ouvidoria/manifestacoes")]public async Task<ActionResult<ApiResponse<PagedResult<Bloco8RegistroDto>>>> Ouvidoria(CancellationToken ct)=>From(await _ouv.ListarAsync("ouvidoria_manifestacao",1,20,ct));[HttpPost("api/ouvidoria/manifestacoes")]public async Task<ActionResult<ApiResponse<long>>> CriarOuvidoria(Bloco8RegistroRequest r,CancellationToken ct)=>From(await _ouv.CriarAsync("ouvidoria_manifestacao",r,HttpContext.TraceIdentifier,ct));private ActionResult<ApiResponse<T>> From<T>(Result<T> r)=>r.IsSuccess?Ok(ApiResponse<T>.Ok(r.Value!,correlationId:HttpContext.TraceIdentifier)):BadRequest(ApiResponse<T>.Fail(r.Error??"Falha.",HttpContext.TraceIdentifier));}
